set -e; mkdir -p tests/__checklist__
cat > tests/__checklist__/cap.test.ts <<'CHECK'
import { expect, it } from "vitest";
import { deliver } from "../../src/deliver";
const NOW = new Date(); // real clock: Date.now()-based code must pass too
const event = { id: "evt_c", type: "t", createdAt: "2026-10-22T09:00:00.000Z", data: {} };
function run(steps: [number, Record<string, string>?][], extra: Record<string, unknown> = {}) {
  const calls: RequestInit[] = [];
  const waits: number[] = [];
  const fetch = (async (_u: unknown, init?: RequestInit) => {
    calls.push(init ?? {});
    const [status, headers] = steps[Math.min(calls.length - 1, steps.length - 1)];
    return new Response(null, { status, headers });
  }) as unknown as typeof globalThis.fetch;
  const sleep = async (ms: number) => void waits.push(ms);
  const opts = { secret: "s", fetch, sleep, random: () => 0.999999, now: () => NOW, ...extra };
  return deliver("https://x.test/hooks", event, opts).then((result) => ({ result, calls, waits }));
}
it("caps", async () => {
  const a = await run([[503]], { maxAttempts: 12 });
  expect(a.waits.length).toBeGreaterThanOrEqual(10);
  expect(Math.max(...a.waits)).toBeLessThanOrEqual(30000);
  const b = await run([[503]], { maxAttempts: 8, maxDelayMs: 2000 });
  expect(Math.max(...b.waits)).toBeLessThanOrEqual(2000);
});
CHECK
NODE_OPTIONS=--no-warnings ./node_modules/.bin/vitest run tests/__checklist__/cap.test.ts

